    14	/**
    15	 * Stock reservations for checkout.
    16	 *
    17	 * Every SKU has three counters: `stock` (units on hand), `reserved` (units
    18	 * held for orders that have not been committed) and `sold`. Available stock
    19	 * is `stock - reserved` and must never go below zero.
    20	 *
    21	 * An order moves reserved -> committed, or reserved -> released. Committing
    22	 * turns its held units into sold units; releasing returns them.
    23	 *
    24	 * The service is called concurrently by every checkout worker.
    25	 */
    26	class InventoryService {
    27	  constructor({ store = new Store(), reservationTtlMs = DEFAULT_TTL_MS, now = () => Date.now() } = {}) {
    28	    this.store = store;
    29	    this.ttl = reservationTtlMs;
    30	    this.now = now;
    31	  }
    32	
    33	  /** Add units to a SKU, creating it if needed. Returns the SKU snapshot. */
    34	  async addStock(sku, qty) {
    35	    assertSku(sku);
    36	    assertQty(qty);
    37	    const item = (await this.store.get(skuKey(sku))) || { stock: 0, reserved: 0, sold: 0 };
    38	    item.stock += qty;
    39	    await this.store.set(skuKey(sku), item);
    40	    return { sku, ...item };
    41	  }
    42	
    43	  /** Units that can still be reserved. */
    44	  async available(sku) {
    45	    const item = await this.getItem(sku);
    46	    return item.stock - item.reserved;
    47	  }
    48	
    49	  /** The SKU's counters. */
    50	  async snapshot(sku) {
    51	    const item = await this.getItem(sku);
    52	    return { sku, stock: item.stock, reserved: item.reserved, sold: item.sold };
    53	  }
    54	
    55	  /**
    56	   * Hold stock for an order: all of its items, or none of them.
    57	   *
    58	   * Idempotent by orderId: checkout retries a timed-out request with the same
    59	   * orderId, and a retry must return the existing reservation rather than
    60	   * hold the stock twice.
    61	   *
    62	   * Rejects with InsufficientStockError when any item cannot be held, and
    63	   * then holds nothing.
    64	   */
    65	  async reserve(orderId, items) {
    66	    assertOrderId(orderId);
    67	    assertItems(items);
    68	    const existing = await this.store.get(orderKey(orderId));
    69	    if (existing) {
    70	      return toReservation(existing);
    71	    }
    72	    for (const { sku, qty } of items) {
    73	      const item = await this.getItem(sku);
    74	      const free = item.stock - item.reserved;
    75	      if (free < qty) {
    76	        throw new InsufficientStockError(sku, qty, free);
    77	      }
    78	      item.reserved += qty;
    79	      await this.store.set(skuKey(sku), item);
    80	    }
    81	    const order = {
    82	      orderId,
    83	      items: items.map(({ sku, qty }) => ({ sku, qty })),
    84	      status: 'reserved',
    85	      createdAt: this.now()
    86	    };
    87	    await this.store.set(orderKey(orderId), order);
    88	    return toReservation(order);
    89	  }
    90	
    91	  /**
    92	   * Turn a reservation into a sale. Idempotent: committing a committed order
    93	   * returns it unchanged. A released order cannot be committed.
    94	   */
    95	  async commit(orderId) {
    96	    const order = await this.getOrder(orderId);
    97	    if (order.status === 'committed') {
    98	      return toReservation(order);
    99	    }
   100	    if (order.status !== 'reserved') {
   101	      throw new OrderStateError(orderId, order.status, 'commit');
   102	    }
   103	    for (const { sku, qty } of order.items) {
   104	      const item = await this.getItem(sku);
   105	      item.reserved -= qty;
   106	      item.stock -= qty;
   107	      item.sold += qty;
   108	      await this.store.set(skuKey(sku), item);
   109	    }
   110	    order.status = 'committed';
   111	    await this.store.set(orderKey(orderId), order);
   112	    return toReservation(order);
   113	  }
   114	
   115	  /**
   116	   * Cancel a reservation and return its units. Idempotent: releasing a
   117	   * released order returns it unchanged. A committed order cannot be
   118	   * released; its units have been sold.
   119	   */
   120	  async release(orderId) {
   121	    const order = await this.getOrder(orderId);
   122	    if (order.status === 'released') {
   123	      return toReservation(order);
   124	    }
   125	    for (const { sku, qty } of order.items) {
   126	      const item = await this.getItem(sku);
   127	      item.reserved -= qty;
   128	      await this.store.set(skuKey(sku), item);
   129	    }
   130	    order.status = 'released';
   131	    await this.store.set(orderKey(orderId), order);
   132	    return toReservation(order);
   133	  }
   134	
   135	  /**
   136	   * Release every reservation older than the TTL that has not been committed
   137	   * or released. Returns the orderIds it released.
   138	   */
   139	  async expire() {
   140	    const cutoff = this.now() - this.ttl;
   141	    const released = [];
   142	    for (const key of await this.store.keys('order:')) {
   143	      const order = await this.store.get(key);
   144	      if (order.createdAt < cutoff) {
   145	        await this.release(order.orderId);
   146	        released.push(order.orderId);
   147	      }
   148	    }
   149	    return released;
   150	  }
   151	
   152	  async getItem(sku) {
   153	    assertSku(sku);
   154	    const item = await this.store.get(skuKey(sku));
   155	    if (!item) {
   156	      throw new UnknownSkuError(sku);
   157	    }
   158	    return item;
   159	  }
   160	
   161	  async getOrder(orderId) {
   162	    assertOrderId(orderId);
   163	    const order = await this.store.get(orderKey(orderId));
   164	    if (!order) {
   165	      throw new UnknownOrderError(orderId);
   166	    }
   167	    return order;
   168	  }
   169	}
