   171	function skuKey(sku) {
   172	  return `sku:${sku}`;
   173	}
   174	
   175	function orderKey(orderId) {
   176	  return `order:${orderId}`;
   177	}
   178	
   179	function toReservation(order) {
   180	  return { orderId: order.orderId, status: order.status, items: order.items.map(({ sku, qty }) => ({ sku, qty })) };
   181	}
   182	
   183	function assertSku(sku) {
   184	  if (typeof sku !== 'string' || sku.trim() === '') {
   185	    throw new ValidationError('sku must be a non-empty string');
   186	  }
   187	}
   188	
   189	function assertOrderId(orderId) {
   190	  if (typeof orderId !== 'string' || orderId.trim() === '') {
   191	    throw new ValidationError('orderId must be a non-empty string');
   192	  }
   193	}
   194	
   195	function assertQty(qty) {
   196	  if (!Number.isInteger(qty) || qty <= 0) {
   197	    throw new ValidationError('qty must be a positive integer');
   198	  }
   199	}
   200	
   201	function assertItems(items) {
   202	  if (!Array.isArray(items) || items.length === 0) {
   203	    throw new ValidationError('items must be a non-empty array');
   204	  }
   205	  const seen = new Set();
   206	  for (const entry of items) {
   207	    if (!entry || typeof entry !== 'object') {
   208	      throw new ValidationError('each item must be an object with sku and qty');
   209	    }
   210	    assertSku(entry.sku);
   211	    assertQty(entry.qty);
   212	    if (seen.has(entry.sku)) {
   213	      throw new ValidationError(`duplicate sku in items: ${entry.sku}`);
   214	    }
   215	    seen.add(entry.sku);
   216	  }
   217	}
