describe('INC-5521: reserved went negative and never recovered', () => {
  it('refuses to release a committed order and leaves its counters alone', async () => {
    const svc = await stocked({ widget: 10 });
    await svc.reserve('o1', one('widget', 3));
    await svc.commit('o1');
    await assert.rejects(svc.release('o1'), err => {
      assert.ok(err instanceof OrderStateError);
      assert.equal(err.status, 'committed');
      return true;
    });
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 7, reserved: 0, sold: 3 });
    assert.equal((await svc.commit('o1')).status, 'committed');
  });

  it('expire releases only reservations that are still held', async () => {
    let t = 0;
    const svc = await stocked({ widget: 10 }, { now: () => t, reservationTtlMs: 1000 });
    await svc.reserve('committed', one('widget', 2));
    await svc.reserve('released', one('widget', 2));
    await svc.reserve('held', one('widget', 2));
    await svc.commit('committed');
    await svc.release('released');
    t = 5000;
    assert.deepEqual(await svc.expire(), ['held']);
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 8, reserved: 0, sold: 2 });
    assert.equal((await svc.commit('committed')).status, 'committed');
    assert.deepEqual(await svc.expire(), []);
  });

  it('expire leaves reservations younger than the TTL alone', async () => {
    let t = 0;
    const svc = await stocked({ widget: 10 }, { now: () => t, reservationTtlMs: 1000 });
    await svc.reserve('o1', one('widget', 2));
    t = 1000;
    assert.deepEqual(await svc.expire(), []);
    assert.equal(await svc.available('widget'), 8);
  });

  it('returns units once when releases and expire race on one order', async () => {
    let t = 0;
    const svc = await stocked({ widget: 10 }, { now: () => t, reservationTtlMs: 1000 });
    await svc.reserve('o1', one('widget', 4));
    t = 5000;
    const [expired, ...releases] = await Promise.all([
      svc.expire(),
      ...Array.from({ length: 5 }, () => svc.release('o1'))
    ]);
    for (const reservation of releases) {
      assert.equal(reservation.status, 'released');
    }
    assert.ok(expired.length <= 1);
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 0, sold: 0 });
  });
});

describe('INC-5521: a retried checkout held units twice', () => {
  it('holds stock once when retries of one order arrive concurrently', async () => {
    const svc = await stocked({ widget: 10 });
    const reservations = await Promise.all(
      Array.from({ length: 5 }, () => svc.reserve('o1', one('widget', 2)))
    );
    for (const reservation of reservations) {
      assert.deepEqual(reservation, { orderId: 'o1', status: 'reserved', items: [{ sku: 'widget', qty: 2 }] });
    }
    assert.equal(await svc.available('widget'), 8);
    await svc.release('o1');
    assert.equal(await svc.available('widget'), 10);
  });

  it('holds what the caller asked for even if it reuses the items array', async () => {
    const svc = await stocked({ widget: 10 });
    const items = one('widget', 2);
    const pending = svc.reserve('o1', items);
    items[0].qty = 5;
    items.push({ sku: 'widget', qty: 1 });
    assert.deepEqual((await pending).items, [{ sku: 'widget', qty: 2 }]);
    assert.equal(await svc.available('widget'), 8);
  });
});

describe('INC-5521: a rejected bundle left its other item held', () => {
  it('holds nothing when a later bundle item is out of stock', async () => {
    const svc = await stocked({ shoe: 5, lace: 1 });
    const bundle = [{ sku: 'shoe', qty: 1 }, { sku: 'lace', qty: 2 }];
    await assert.rejects(svc.reserve('o1', bundle), err => {
      assert.ok(err instanceof InsufficientStockError);
      assert.equal(err.sku, 'lace');
      assert.equal(err.available, 1);
      return true;
    });
    assert.equal(await svc.available('shoe'), 5);
    assert.equal(await svc.available('lace'), 1);
    // The failed attempt left no order behind, so a retry after restocking holds the bundle.
    await svc.addStock('lace', 1);
    assert.equal((await svc.reserve('o1', bundle)).status, 'reserved');
    assert.equal(await svc.available('shoe'), 4);
    assert.equal(await svc.available('lace'), 0);
  });

  it('holds nothing when a later bundle item is unknown', async () => {
    const svc = await stocked({ shoe: 5 });
    await assert.rejects(svc.reserve('o1', [{ sku: 'shoe', qty: 1 }, { sku: 'ghost', qty: 1 }]), UnknownSkuError);
    assert.equal(await svc.available('shoe'), 5);
    await assert.rejects(svc.commit('o1'), UnknownOrderError);
  });

  it('gives the last unit of a shared item to one of two racing bundles', async () => {
    const svc = await stocked({ shoe: 5, lace: 1 });
    const bundle = [{ sku: 'shoe', qty: 1 }, { sku: 'lace', qty: 1 }];
    const { fulfilled, rejected } = partition(
      await Promise.allSettled([svc.reserve('o1', bundle), svc.reserve('o2', bundle)])
    );
    assert.equal(fulfilled.length, 1);
    assert.ok(rejected[0] instanceof InsufficientStockError);
    assert.equal(await svc.available('shoe'), 4);
    assert.equal(await svc.available('lace'), 0);
  });
});

describe('INC-5521: sold counts higher than orders shipped', () => {
  it('counts a sale once when commit retries race', async () => {
    const svc = await stocked({ widget: 10 });
    await svc.reserve('o1', one('widget', 3));
    const commits = await Promise.all(Array.from({ length: 5 }, () => svc.commit('o1')));
    for (const reservation of commits) {
      assert.equal(reservation.status, 'committed');
    }
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 7, reserved: 0, sold: 3 });
  });

  it('lets exactly one of a racing commit and release win', async () => {
    const svc = await stocked({ widget: 10 });
    await svc.reserve('o1', one('widget', 2));
    const [commit, release] = await Promise.allSettled([svc.commit('o1'), svc.release('o1')]);
    const winners = [commit, release].filter(r => r.status === 'fulfilled');
    const losers = [commit, release].filter(r => r.status === 'rejected');
    assert.equal(winners.length, 1);
    assert.ok(losers[0].reason instanceof OrderStateError);
    const expected = commit.status === 'fulfilled'
      ? { sku: 'widget', stock: 8, reserved: 0, sold: 2 }
      : { sku: 'widget', stock: 10, reserved: 0, sold: 0 };
    assert.deepEqual(await svc.snapshot('widget'), expected);
  });

  it('never both sells and expires an order committed while expire runs', async () => {
    let t = 0;
    const svc = await stocked({ widget: 20 }, { now: () => t, reservationTtlMs: 1000 });
    const orderIds = Array.from({ length: 20 }, (_, i) => `o${i}`);
    for (const orderId of orderIds) {
      await svc.reserve(orderId, one('widget'));
    }
    t = 5000;
    const [expired, ...commits] = await Promise.allSettled([
      svc.expire(),
      ...orderIds.map(orderId => svc.commit(orderId))
    ]);
    const committed = commits.filter(r => r.status === 'fulfilled').length;
    for (const r of commits.filter(r => r.status === 'rejected')) {
      assert.ok(r.reason instanceof OrderStateError);
    }
    assert.equal(committed + expired.value.length, 20);
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 20 - committed, reserved: 0, sold: committed });
  });
});

describe('locking scope', () => {
  it('lets calls on other SKUs and orders finish while one SKU is stuck', async () => {
    const store = new GatedStore();
    const svc = new InventoryService({ store });
    await svc.addStock('slow', 5);
    await svc.addStock('fast', 5);
    const unblock = store.block('sku:slow');
    const stuck = [svc.reserve('slow-order', one('slow')), svc.addStock('slow', 1)];
    try {
      const unrelated = (async () => {
        await svc.reserve('fast-1', one('fast'));
        await svc.commit('fast-1');
        await svc.reserve('fast-2', one('fast'));
        await svc.release('fast-2');
        await svc.addStock('fast', 1);
      })();
      assert.equal(await settlesWithin(unrelated, 1000), true, 'calls on "fast" waited for calls on "slow"');
      await unrelated;
    } finally {
      unblock();
    }
    await Promise.all(stuck);
    assert.deepEqual(await svc.snapshot('fast'), { sku: 'fast', stock: 5, reserved: 0, sold: 1 });
    assert.deepEqual(await svc.snapshot('slow'), { sku: 'slow', stock: 6, reserved: 1, sold: 0 });
  });

  it('does not deadlock bundles that list the same SKUs in opposite orders', async () => {
    const svc = await stocked({ a: 100, b: 100, c: 100 });
    const orders = ['a', 'b', 'c'];
    const all = Promise.all(Array.from({ length: 60 }, (_, i) => {
      const skus = i % 2 === 0 ? orders : [...orders].reverse();
      return svc.reserve(`o${i}`, skus.map(sku => ({ sku, qty: 1 })));
    }));
    assert.equal(await settlesWithin(all, 2000), true, 'bundles deadlocked');
    for (const sku of orders) {
      assert.equal(await svc.available(sku), 40);
    }
  });
});

describe('randomized concurrent workload', () => {
  const SKUS = ['a', 'b', 'c', 'd'];
  const EXPECTED_ERRORS = [InsufficientStockError, UnknownOrderError, OrderStateError];

  for (const seed of [1, 2, 3, 4, 5, 6, 7, 8]) {
    it(`keeps counters equal to what the order records say (seed ${seed})`, async () => {
      const store = new JitterStore(seed);
      const random = mulberry32(seed * 7919);
      const pick = list => list[Math.floor(random() * list.length)];
      let clock = 0;
      const svc = new InventoryService({ store, now: () => clock, reservationTtlMs: 30 });
      const added = {};
      for (const sku of SKUS) {
        await svc.addStock(sku, 15);
        added[sku] = 15;
      }

      const orderIds = [];
      const expiredLists = [];
      const calls = [];
      for (let i = 0; i < 400; i++) {
        clock += 1;
        const roll = random();
        if (roll < 0.4 || orderIds.length === 0) {
          const orderId = orderIds.length > 0 && random() < 0.2 ? pick(orderIds) : `o${i}`;
          if (!orderIds.includes(orderId)) {
            orderIds.push(orderId);
          }
          const skus = [...SKUS].sort(() => random() - 0.5).slice(0, 1 + Math.floor(random() * 2));
          calls.push(svc.reserve(orderId, skus.map(sku => ({ sku, qty: 1 + Math.floor(random() * 3) }))));
        } else if (roll < 0.6) {
          calls.push(svc.commit(pick(orderIds)));
        } else if (roll < 0.75) {
          calls.push(svc.release(pick(orderIds)));
        } else if (roll < 0.9) {
          const sku = pick(SKUS);
          const qty = 1 + Math.floor(random() * 3);
          calls.push(svc.addStock(sku, qty).then(() => {
            added[sku] += qty;
          }));
        } else {
          calls.push(svc.expire().then(ids => expiredLists.push(ids)));
        }
        if (random() < 0.5) {
          await tick();
        }
      }

      for (const result of await Promise.allSettled(calls)) {
        if (result.status === 'rejected') {
          assert.ok(EXPECTED_ERRORS.some(type => result.reason instanceof type), `unexpected rejection: ${result.reason?.stack}`);
        }
      }

      const expected = Object.fromEntries(SKUS.map(sku => [sku, { reserved: 0, sold: 0 }]));
      const statuses = new Map();
      for (const key of await store.keys('order:')) {
        const order = await store.get(key);
        statuses.set(order.orderId, order.status);
        for (const { sku, qty } of order.items) {
          if (order.status === 'reserved') {
            expected[sku].reserved += qty;
          } else if (order.status === 'committed') {
            expected[sku].sold += qty;
          }
        }
      }
      for (const sku of SKUS) {
        const { reserved, sold } = expected[sku];
        const snapshot = await svc.snapshot(sku);
        assert.deepEqual(snapshot, { sku, stock: added[sku] - sold, reserved, sold });
        assert.ok(snapshot.stock - snapshot.reserved >= 0, `${sku} oversold: ${JSON.stringify(snapshot)}`);
      }

      const expiredIds = expiredLists.flat();
      assert.equal(new Set(expiredIds).size, expiredIds.length, 'an order was expired twice');
      for (const orderId of expiredIds) {
        assert.equal(statuses.get(orderId), 'released');
      }
    });
  }
});

