'use strict';

/**
 * Mutual exclusion per key for async callers in one process. Callers holding
 * different keys never wait for each other. A key has an entry only while it
 * is held, so the table's size is bounded by concurrent callers, not by the
 * number of keys ever locked.
 */
class KeyedLock {
  // key -> resolvers of callers waiting for it, in arrival order.
  #waiting = new Map();

  /** Number of keys currently held. */
  get size() {
    return this.#waiting.size;
  }

  /**
   * Run `fn` while holding every key in `keys`, then release them, also when
   * `fn` throws. Keys are taken in sorted order, so callers asking for
   * overlapping sets cannot deadlock. Not reentrant: asking for a key the
   * caller already holds waits forever.
   */
  async run(keys, fn) {
    const ordered = [...new Set(keys)].sort();
    const held = [];
    try {
      for (const key of ordered) {
        await this.#acquire(key);
        held.push(key);
      }
      return await fn();
    } finally {
      for (const key of held.reverse()) {
        this.#release(key);
      }
    }
  }

  #acquire(key) {
    const queue = this.#waiting.get(key);
    if (!queue) {
      this.#waiting.set(key, []);
      return Promise.resolve();
    }
    return new Promise(resolve => queue.push(resolve));
  }

  // Hands the key straight to the next waiter so a newcomer cannot jump the queue.
  #release(key) {
    const next = this.#waiting.get(key).shift();
    if (next) {
      next();
    } else {
      this.#waiting.delete(key);
    }
  }
}

module.exports = { KeyedLock };

