'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { KeyedLock } = require('../src/keyed-lock');

function tick() {
  return new Promise(resolve => setImmediate(resolve));
}

describe('KeyedLock', () => {
  it('runs callers of one key one at a time, in arrival order', async () => {
    const lock = new KeyedLock();
    const events = [];
    await Promise.all([1, 2, 3].map(n => lock.run(['k'], async () => {
      events.push(`start ${n}`);
      await tick();
      events.push(`end ${n}`);
    })));
    assert.deepEqual(events, ['start 1', 'end 1', 'start 2', 'end 2', 'start 3', 'end 3']);
  });

  it('returns what fn returns and forgets keys once no one holds them', async () => {
    const lock = new KeyedLock();
    const pending = lock.run(['a', 'b', 'a'], async () => {
      assert.equal(lock.size, 2);
      return 'done';
    });
    assert.equal(await pending, 'done');
    assert.equal(lock.size, 0);
  });

  it('releases every key when fn throws', async () => {
    const lock = new KeyedLock();
    await assert.rejects(lock.run(['a', 'b'], async () => {
      throw new Error('boom');
    }), /boom/);
    assert.equal(lock.size, 0);
    assert.equal(await lock.run(['b', 'a'], () => 'next caller got in'), 'next caller got in');
  });
});

